  drag={...startPan(view,$('svg').getScreenCTM(),{x:e.clientX,y:e.clientY}),vertex:vertex===undefined?null:Number(vertex),moved:false,diamondId:e.target.closest('[data-diamond-id]')?.dataset.diamondId};
