// Botón «Capas» de la barra del plano: apaga mobiliario, ejes de grilla y relleno de pasillos. Los pisos sin láminas DWG lo explican.
function montarCapasDibujo(){
 const bar=document.querySelector('.disciplineBar');if(!bar||bar.querySelector('.capasDibujo'))return;
 const capas=capasDibujo(),caja=document.createElement('div');caja.className='capasDibujo';
 caja.innerHTML=`<button type="button" class="capasBoton" aria-expanded="false" aria-controls="capasMenu" title="Capas del dibujo">Capas</button><div id="capasMenu" class="capasMenu" role="group" aria-label="Capas del dibujo" hidden>${capas.length?capas.map(c=>`<label class="check"><input type="checkbox" data-capa="${esc(c.id)}" ${c.visible?'checked':''}> ${esc(c.nombre)}</label>`).join('')+'<small>Se recuerda en este equipo para todos los pisos.</small>':`<small>El plano de ${esc(nivel.nombre)} viene de PDF sin capas: el mobiliario, los ejes y el relleno se podrán apagar cuando se carguen sus láminas DWG.</small>`}</div>`;
 bar.insertBefore(caja,bar.querySelector('#disciplineStatus'));
 const boton=caja.querySelector('.capasBoton'),menu=caja.querySelector('.capasMenu'),abrir=v=>{menu.hidden=!v;boton.setAttribute('aria-expanded',String(v));};
 boton.onclick=()=>abrir(menu.hidden);
 document.addEventListener('click',e=>{if(!menu.hidden&&!caja.contains(e.target))abrir(false);});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){abrir(false);boton.focus();}});
 menu.querySelectorAll('[data-capa]').forEach(i=>i.onchange=()=>mostrarCapa(i.dataset.capa,i.checked));
}
