$('detailResize').addEventListener('pointerup',()=>{resizeStart=null;updateTiles();});
$('detailResize').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const w=document.querySelector('.right').getBoundingClientRect().width;document.body.style.setProperty('--detail',Math.max(310,Math.min(innerWidth*.55,w+(e.key==='ArrowLeft'?20:-20)))+'px');updateTiles();}});

function bindExport(){$('exportPDF').onclick=()=>{ $('modal').close();exportAtlas();};$('exportPNG').onclick=()=>{$('modal').close();exportAtlas('png');};}

async function addExportLegend(pdf,markingDocument,comparacion=null){
 const font=await pdf.embedFont(PDFLib.StandardFonts.Helvetica);let p=pdf.addPage([595,842]),y=800;
 const lines=['ATLAS HPC - '+nivel.nombre+' / '+atlas.scope.name,...(markingDocument?markingLegend(markingDocument,comparacion):$('activeLegend').hidden?['Plano monocromatico / consulta actual']:[$('activeLegend').innerText]),'Superficies auxiliares de consulta. No certifican limites tecnicos.','Fuentes: '+data.documents.map(d=>d.code+' ('+d.revision+')').join('; ')];
 for(const raw of lines){const words=raw.replace(/[^\x20-\xFF\n]/g,'-').split(/\s+/);let line='';for(const word of words){if(font.widthOfTextAtSize(line+' '+word,10)>510){p.drawText(line,{x:40,y,size:10,font});y-=16;line=word;if(y<40){p=pdf.addPage([595,842]);y=800;}}else line+=(line?' ':'')+word;}if(line){p.drawText(line,{x:40,y,size:10,font});y-=22;if(y<40){p=pdf.addPage([595,842]);y=800;}}}
}

function revertLast(r){const old=JSON.parse(r.history[0].before_json);modal(`<h2>Revertir última corrección</h2><p>${esc(r.code)} · Se conservará todo el historial.</p><form id="revertForm"><label>Responsable<input name="responsible" required></label><label>Motivo<textarea name="reason" required></textarea></label><button class="primary">Guardar reversión</button></form>`);$('revertForm').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);const b={version:r.version,responsible:f.get('responsible'),reason:'Reversión: '+f.get('reason'),code:old.code,name:old.name,finishes:old.finishes,diamond_bbox:old.diamond_bbox,polygon:old.polygon,holes:old.holes,geometry_parts:old.geometry_parts||null,geometry_status:'Pendiente de revisión',status:'Pendiente de revisión'};const saved=await api('/api/rooms/'+r.id,{method:'PATCH',body:JSON.stringify(b)});data.rooms[data.rooms.findIndex(x=>x.id===r.id)]=saved;selected=saved;await prepareViewer(atlas,uniqueRooms(data.rooms),aliases,await loadRuntime());$('modal').close();await runSearch();selected=saved;renderDetail();render();toast('Reversión guardada como nueva corrección, pendiente de revisión.');}catch(err){toast(err.message);}};}

for(const eventName of ['atlas-before-update','atlas-before-floor-change'])window.addEventListener(eventName,event=>{if(edit||document.querySelector('#contourEditor[open],#modal[open] form')){event.preventDefault();toast('Guarda o cierra la edición antes de continuar.');}});
window.addEventListener('atlas-floor-resume',()=>{ui?.show('map');requestAnimationFrame(()=>{setView(view);updateTiles();});});

window.addEventListener('atlas-room-progress-changed',()=>{const section=$('detail').querySelector('.roomProgress[open]');if(section&&selected)renderRoomProgress($('roomProgressEvidence'),selected,esc);});
